# Try a local search / randomized approach
import random

edges = []
for g in range(5):
    for i in range(4):
        for j in range(i+1,4):
            edges.append((g*4+i, g*4+j))
for g in range(4):
    for i in range(4):
        edges.append((g*4+i, (g+1)*4+i))

n = 20
E = 46

def score(labels):
    ds = [abs(labels[a]-labels[b]) for a,b in edges]
    return len(set(ds))

def random_labels():
    return random.sample(range(E+1), n)

best = 0
best_sol = None
random.seed(42)

for trial in range(50):
    labels = random_labels()
    # simulated annealing
    import math
    T = 5.0
    cur_score = score(labels)
    for it in range(200000):
        # pick two positions to swap, or swap a label with unused
        used = set(labels)
        unused = [x for x in range(E+1) if x not in used]
        if random.random() < 0.5 and unused:
            i = random.randrange(n)
            old = labels[i]
            new = random.choice(unused)
            labels[i] = new
            ns = score(labels)
            if ns > cur_score or random.random() < math.exp((ns-cur_score)/T):
                cur_score = ns
            else:
                labels[i] = old
        else:
            i,j = random.sample(range(n),2)
            labels[i], labels[j] = labels[j], labels[i]
            ns = score(labels)
            if ns > cur_score or random.random() < math.exp((ns-cur_score)/T):
                cur_score = ns
            else:
                labels[i], labels[j] = labels[j], labels[i]
        T *= 0.99999
        if cur_score == 46:
            break
    if cur_score > best:
        best = cur_score
        best_sol = labels[:]
        print(trial, best)
    if best == 46:
        break

print("best:", best)
print(best_sol)
